package mdn.jh.automation.devices.shelly;
import javax.swing.JPanel;import org.w3c.dom.*;import mdn.jh.automation.io.DataComponentStub;import mdn.jh.automation.io.source.DataSource;
public class ShellyDataSource extends DataSource{private static final long serialVersionUID=1L;private int channel;private boolean value,valid;public ShellyDataSource(){}public ShellyDataSource(int c){channel=c;setStatusMessage("Physical input "+c);}public int getChannel(){return channel;}public void updateValue(boolean v){value=v;valid=true;updateMyOutputs();}public void invalidate(){valid=false;}@Override public boolean getOutputAsBoolean(){return value;}@Override public double getOutputAsNumber(){return value?1:0;}@Override public String getOutputAsString(){return Boolean.toString(value);}@Override public int getDataTypeOutput(){return DataComponentStub.TYPE_BOOLEAN_IO;}@Override public boolean isDataValid(){return valid;}@Override public JPanel getSpecificDetailsPanel(){return null;}@Override public Node getStorageXML(Document d){Element r=getStorage(d),e=d.createElement("ShellyInput");e.setAttribute("channel",Integer.toString(channel));r.appendChild(e);return r;}@Override public boolean initDataComponent(Node n)throws Exception{initDataSource(n);NodeList l=n.getChildNodes();for(int i=0;i<l.getLength();i++)if("ShellyInput".equals(l.item(i).getNodeName()))channel=Integer.parseInt(l.item(i).getAttributes().getNamedItem("channel").getNodeValue());setStatusMessage("Physical input "+channel);return true;}}
